module ot_hbm_hc_tail_rest_core_fsr #(
    parameter integer SMUT = 0,
    parameter integer CAP  = 769 - ((SMUT == 1) ? 1 : 0),       // sink launch -> out_valid at this core (faces + fsr LAT + FQ)
    parameter integer MUT_PRE = 0,
    parameter integer PREDECODE_INDEX = 0,
    parameter integer REFORM = 1,     // RE-FORM 11-03 (0 = bench gold only)
    parameter integer REFORM_COMB = 0, // bench only (u_tail REFORM_COMB)
    parameter integer TE = (REFORM != 0) ? 279 : 197,   // u_tail EREADY (the bench checks it equals u_tail.EREADY)
    parameter integer SKL = TE + 1,   // sink launch age: every t word written back
    parameter integer NSTA = 0,       // stations on the rest -> sk sk_en hop
    parameter integer MUT_EN = 0,     // bench only: 1 = sk_en one cycle early (must FAIL)
    parameter integer L = SKL + CAP + 3
)(
    input  wire          clk, rst_n,
    input  wire          launch,
    input  wire [767:0]  mixes, bases,
    input  wire [95:0]   scales,
    output reg           result_v,
    output wire [767:0]  result,
    output wire          fault,
    output wire sk_en_sk, sk_in_valid,
    output wire [511:0] sk_in_e,
    input wire sk_in_ready, sk_out_valid, sk_fault,
    input wire [511:0] sk_y
);
