    wire sclk = 1'b1;
    wire sk_en_o = 1'b0;   // pin kept (rest table unchanged), no load at the parent
    reg active, sl, armed; reg [11:0] age, sage;
    wire tv; wire tf;
    reg capture_q;
    ot_hbm_hc_tail_static_rest_fsr #(.MUT_PRE(MUT_PRE), .NSTA(NSTA), .PREDECODE_INDEX(PREDECODE_INDEX), .REFORM(REFORM), .REFORM_COMB(REFORM_COMB)) u_tail (.clk(clk), .sk_en(sclk), .sk_en_sk(sk_en_o), .rst_n(rst_n), .launch(launch),
        .mixes(mixes), .bases(bases), .scales(scales), .sink_launch(sl), .sink_capture(capture_q),
        .e_ready(), .result_v(tv), .result(result), .fault(tf),
        .sk_in_e(sk_in_e), .sk_in_ready(sk_in_ready), .sk_out_valid(sk_out_valid), .sk_fault(sk_fault), .sk_y(sk_y));
    assign sk_en_sk = sk_en_o; assign sk_in_valid = sl;
