        if (!rst_n) begin active <= 0; sl <= 0; armed <= 0; age <= 0; sage <= 0; capture_q <= 0; result_v <= 0;
                          own_fault <= 0; captured <= 0; end
        else begin
            capture_q <= 1'b0; result_v <= 1'b0;
            if (active) age <= age + 1'b1;
            if (launch) begin
                if (active) own_fault <= 1'b1;
                active <= 1'b1; age <= 12'd1; armed <= 1'b0; captured <= 1'b0;
            end
            // sink launch window: set on the first wrap edge at age >= SKL, cleared on the next wrap edge
            if (active && !armed && age >= 12'(SKL) && wrap) begin sl <= 1'b1; armed <= 1'b1; sage <= 12'd1; end
            else if (sl && wrap) sl <= 1'b0;
            if (armed && !captured) begin
                sage <= sage + 1'b1;
                if (sage == 12'(CAP)) begin capture_q <= 1'b1; captured <= 1'b1; end
            end
            if (active && age == 12'(L - 1)) begin
                result_v <= 1'b1; active <= 1'b0;
                if (!captured) own_fault <= 1'b1;
            end
        end
    end
endmodule
